/*
 * timelib_config.h -- generated by configure in an upstream build;
 * hand-kept here.  `ext/date/lib' reaches it because the mkfile
 * passes `-DHAVE_TIMELIB_CONFIG_H=1'.
 *
 * It exists to route timelib's allocation through the Zend allocator,
 * which is the whole of its content upstream as well -- this is a
 * copy of what configure writes, not a port of anything.
 */
#include <php_config.h>

#include <inttypes.h>
#include <stdint.h>

#include "zend.h"

#define timelib_malloc  emalloc
#define timelib_realloc erealloc
#define timelib_calloc  ecalloc
#define timelib_strdup  estrdup
#define timelib_strndup estrndup
#define timelib_free    efree
